const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const paymentGateway = String(payload.paymentGateway || payload.gateway || 'razorpay').toLowerCase();
const transactionId = String(payload.transactionId || payload.paymentId || payload.id || 'txn_unknown').trim();
const invoiceId = String(payload.invoiceId || payload.invoice_id || 'inv_unknown').trim();
const projectId = String(payload.projectId || payload.project_id || '').trim();
const milestoneNumber = Number(payload.milestoneNumber || payload.milestone || 1);
const expectedAmount = Number(payload.expectedAmount || payload.invoiceTotal || 0);
const amountPaid = Number(payload.amountPaid || payload.amount || 0);
const currency = String(payload.currency || 'INR').toUpperCase();
const gatewayFee = Number(payload.gatewayFee || payload.fee || 0);
const netSettled = Number(payload.netSettled || (amountPaid - gatewayFee));

const delta = Math.abs(amountPaid - expectedAmount);
const isFullyPaid = expectedAmount > 0 ? delta <= 0.01 : amountPaid > 0;
const isUnderpaid = expectedAmount > 0 && amountPaid < expectedAmount - 0.01;
const isOverpaid = expectedAmount > 0 && amountPaid > expectedAmount + 0.01;

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    reconciliation: {
      paymentGateway,
      transactionId,
      invoiceId,
      projectId,
      milestoneNumber,
      expectedAmount,
      amountPaid,
      currency,
      gatewayFee,
      netSettled,
      isFullyPaid,
      isUnderpaid,
      isOverpaid,
      reconciledAt: new Date().toISOString()
    }
  }
}];

const item = $input.first().json;
const recon = item.reconciliation;

const year = new Date().getFullYear();
const seq = Math.floor(1000 + Math.random() * 9000);
const receiptNumber = `LIT-RCP-${year}-${seq}`;

const milestoneUnlock = {
  projectId: recon.projectId,
  milestoneNumber: recon.milestoneNumber,
  status: 'ACTIVE_IN_PROGRESS',
  billingState: 'PAID',
  receiptNumber,
  transactionId: recon.transactionId,
  settlementTimestamp: new Date().toISOString(),
  notificationTarget: 'Client & Engineering Lead'
};

return [{
  json: {
    eventId: item.eventId,
    status: 'payment_reconciled_unlocked',
    detail: {
      reconciliation: recon,
      milestoneUnlock,
      receiptNumber
    }
  }
}];

const item = $input.first().json;
const recon = item.reconciliation;

const discrepancy = {
  type: recon.isUnderpaid ? 'UNDERPAYMENT_DEFICIT' : 'OVERPAYMENT_SURPLUS',
  expectedAmount: recon.expectedAmount,
  amountPaid: recon.amountPaid,
  currency: recon.currency,
  invoiceId: recon.invoiceId,
  transactionId: recon.transactionId,
  requiresManualReview: true,
  escalatedTo: 'Vikash Saravanan (Finance Operations)'
};

return [{
  json: {
    eventId: item.eventId,
    status: 'payment_discrepancy_flagged',
    detail: {
      reconciliation: recon,
      discrepancy
    }
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'processed',
  detail: item.json.detail || {}
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
